mapper.select:
SELECT CASE WHEN MAX(CASE WHEN p.permission_code = 'PERM_WRITE' THEN 1 ELSE 0 END) = 1 THEN 'write' WHEN MAX(CASE WHEN p.permission_code = 'PERM_READ' THEN 1 ELSE 0 END) = 1 THEN 'read' ELSE 'none' END AS permissionLevel FROM tb_role_menu_permission rmp INNER JOIN tb_menu m ON rmp.menu_id = m.menu_id INNER JOIN tb_role r ON rmp.role_id = r.role_id INNER JOIN tb_permission p ON rmp.permission_id = p.permission_id INNER JOIN tb_tenant_subscription ts ON ts.tenant_id = r.tenant_id AND ts.subscription_status = 'ACTIVE' INNER JOIN tb_plan_menu pm ON pm.plan_id = ts.plan_id AND pm.menu_code = m.menu_code AND pm.use_at = 'Y' WHERE r.role_code = #{roleCode} AND m.menu_url = #{menuUrl}
AND r.tenant_id = #{tenantId}
AND m.use_at = 'Y' AND p.use_at = 'Y'
